export const STORY_SOURCES = {
  1: {"story":"Brian Lara made 400 not out off 582 balls against England at the Antigua Recreation Ground, St John's, in April 2004, taking the Test record back from Matthew Hayden's 380 six months after losing it. He batted for 778 minutes and West Indies declared at 751 for 5. England had won the first three Tests and the match was drawn.","sources":[{"url":"https://en.wikipedia.org/wiki/English_cricket_team_in_the_West_Indies_in_2003%E2%80%9304","label":"Wikipedia: English cricket team in the West Indies in 2003-04"},{"url":"https://www.cricket.com.au/news/world-record-highest-individual-test-score-progression-400-lara-hayden-sobers-bradman-bannerman/2018-04-18","label":"Cricket Australia: When Brian Lara joined the legends"}]},
  2: {"story":"Matthew Hayden made 380 off 437 balls against Zimbabwe at the WACA, Perth, in October 2003, passing Brian Lara's Test record of 375. He batted for about 10 hours as Australia made 735 for 6 declared and won by an innings and 175 runs. Lara took the record back six months later.","sources":[{"url":"https://en.wikipedia.org/wiki/Zimbabwean_cricket_team_in_Australia_in_2003%E2%80%9304","label":"Wikipedia: Zimbabwean cricket team in Australia in 2003-04"},{"url":"https://www.icc-cricket.com/news/matthew-hayden-an-imperious-and-imposing-giant","label":"ICC: Matthew Hayden, an imperious and imposing giant"}]},
  3: {"story":"Brian Lara made 375 against England at the Antigua Recreation Ground, St John's, in April 1994, breaking Garfield Sobers' 365 not out. Sobers' record had stood for 36 years.","sources":[{"url":"https://www.icc-cricket.com/news/400-brilliant-bridgetown-and-eclipsing-sobers-10-of-the-best-from-lara","label":"ICC: 400*, brilliant Bridgetown, and eclipsing Sobers"},{"url":"https://www.cricket.com.au/news/3304888","label":"Cricket Australia: Charles to Brian, a world record's run"}]},
  4: {"story":"Mahela Jayawardene made 374 off 572 balls against South Africa at the SSC, Colombo, in July 2006. He and Kumar Sangakkara added 624, the highest partnership in first-class cricket. Sri Lanka declared at 756 for 5 and won by an innings and 153 runs. It is the highest Test score by a Sri Lankan.","sources":[{"url":"https://en.wikipedia.org/wiki/South_African_cricket_team_in_Sri_Lanka_in_2006","label":"Wikipedia: South African cricket team in Sri Lanka in 2006"},{"url":"https://www.icc-cricket.com/news/the-best-of-mahela-jayawardene-his-top-test-innings","label":"ICC: The best of Mahela Jayawardene, his top Test innings"}]},
  6: {"story":"Garfield Sobers made 365 not out against Pakistan at Sabina Park, Kingston, in 1958, the highest score in Test cricket at the time. West Indies made 790 for 3 declared and won the match by an innings and 174 runs.","sources":[{"url":"https://en.wikipedia.org/wiki/Pakistani_cricket_team_in_the_West_Indies_in_1957%E2%80%9358","label":"Wikipedia: Pakistani cricket team in the West Indies in 1957-58"},{"url":"https://www.wisden.com/wisden-cricketers-almanack/sir-garfield-sobers-crickets-finest-all-round-player-almanack","label":"Wisden: Sir Garfield Sobers, cricket's finest all-round player"}]},
  7: {"story":"Len Hutton made 364 against Australia at The Oval in the fifth Test, in August 1938. England made 903 for 7 declared and won by an innings and 579 runs. His score stood as the highest individual Test score for nearly 20 years. The series was drawn 1-1 and Australia kept the Ashes.","sources":[{"url":"https://en.wikipedia.org/wiki/Australian_cricket_team_in_England_in_1938","label":"Wikipedia: Australian cricket team in England in 1938"},{"url":"https://www.icc-cricket.com/hall-of-fame/hall-of-famers/hall-of-famer-len-hutton","label":"ICC Hall of Fame: Len Hutton"}]},
  9: {"story":"Hanif Mohammad made 337 against West Indies at Bridgetown in January 1958, in the first Test of the series. Pakistan were asked to follow on, trailing by 473 runs, and he batted for 970 minutes as they reached 657 for 8 declared. The match was drawn.","sources":[{"url":"https://www.icc-cricket.com/hall-of-fame/hall-of-famers/hall-of-famer-hanif-mohammad","label":"ICC Hall of Fame: Hanif Mohammad"},{"url":"https://en.wikipedia.org/wiki/Pakistani_cricket_team_in_the_West_Indies_in_1957%E2%80%9358","label":"Wikipedia: Pakistani cricket team in the West Indies in 1957-58"}]},
  11: {"story":"David Warner made 335 not out off 418 balls against Pakistan at Adelaide in the day-night second Test of 2019, after Australia had won the first by an innings and five runs. Tim Paine declared at 3 for 589 once Warner had passed Don Bradman's 334. Australia won by an innings and 48 runs.","sources":[{"url":"https://en.wikipedia.org/wiki/Pakistani_cricket_team_in_Australia_in_2019%E2%80%9320","label":"Wikipedia: Pakistani cricket team in Australia in 2019-20"},{"url":"https://www.cricket.com.au/news/david-warner-triple-century-australia-pakistan-second-test-adelaide-oval-don-bradman-mark-taylor/2019-11-30","label":"Cricket Australia: Warner joins illustrious company with triple-century"}]},
  12: {"story":"Mark Taylor made 334 not out off 564 balls against Pakistan at Peshawar in October 1998, in the second Test, with Australia 1-0 up. He batted for about 12 hours across two days and Australia declared at 4 for 599 the next morning, which left him on the same score as Don Bradman's 334 in 1930. The match was drawn and Australia won the series 1-0.","sources":[{"url":"https://en.wikipedia.org/wiki/Australian_cricket_team_in_Pakistan_in_1998%E2%80%9399","label":"Wikipedia: Australian cricket team in Pakistan in 1998-99"},{"url":"https://www.cricket.com.au/news/mark-taylor-334-not-out-declaration-pakistan-test-on-this-day-1998-sir-donald-bradman-high-score/2021-10-16","label":"Cricket Australia: On this day, Taylor equals Bradman with 334"}]},
  13: {"story":"Don Bradman made 334 against England at Leeds, 1930. He came in at 1 for 2 after Jackson fell for 1, and was 309 not out at the end of the first day (Australia 458 for 3). He was out the next morning for 334 off 448 balls, the first triple century in Test cricket. Australia made 566, England followed on, and the match was drawn with the series level at 1–1.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1930/AUS_IN_ENG/AUS_ENG_T3_11-15JUL1930.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1930_Ashes_series","label":"Wikipedia: 1930 Ashes"},{"url":"https://www.footyalmanac.com.au/headingley-1930/","label":"Almanac Cricket: Headingley 1930"},{"url":"https://cricmash.com/flashes-to-remember/ashes-1930-bradmans-309-in-a-day","label":"Cricmash: Bradman’s 309 in a day"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  14: {"story":"Graham Gooch made 333 off 485 balls against India at Lord's in the first Test of July 1990, hitting 43 fours and three sixes in 627 minutes. England made 653 for 4 declared. He made 123 in the second innings, England set India 472 and won by 247 runs. England won the three-Test series 1-0.","sources":[{"url":"https://en.wikipedia.org/wiki/Indian_cricket_team_in_England_in_1990","label":"Wikipedia: Indian cricket team in England in 1990"},{"url":"https://www.wisden.com/wisden-cricketers-almanack/england-india-lords-1990","label":"Wisden: England v India at Lord's, 1990"}]},
  15: {"story":"Chris Gayle made 333 off 437 balls against Sri Lanka at Galle in November 2010, in the first Test of the series. He was 219 not out at the end of the first day, when West Indies were 362 for 2. West Indies made 580 for 9 declared, Sri Lanka followed on after making 378, and the match was drawn.","sources":[{"url":"https://en.wikipedia.org/wiki/West_Indian_cricket_team_in_Sri_Lanka_in_2010%E2%80%9311","label":"Wikipedia: West Indian cricket team in Sri Lanka in 2010-11"},{"url":"https://www.icc-cricket.com/news/gayle-flays-sri-lanka-with-a-double-hundred","label":"ICC: Gayle flays Sri Lanka with a double hundred"}]},
  16: {"story":"Michael Clarke made 329 not out off 468 balls against India at Sydney in January 2012, in the second Test, after Australia had won the first. Australia made 4 for 659 declared and won by an innings and 68 runs.","sources":[{"url":"https://en.wikipedia.org/wiki/Indian_cricket_team_in_Australia_in_2011%E2%80%9312","label":"Wikipedia: Indian cricket team in Australia in 2011-12"},{"url":"https://www.cricket.com.au/news/3285699","label":"Cricket Australia: Australia's Test triple centurions"}]},
  20: {"story":"Kumar Sangakkara made 319 against Bangladesh at Chittagong in February 2014, his career best and first Test triple century, with 32 fours and eight sixes. It was the second Test, and Sri Lanka were 1-0 up after winning the first by an innings and 248 runs. Sri Lanka made 587 and the match was drawn, so they won the series 1-0.","sources":[{"url":"https://en.wikipedia.org/wiki/Sri_Lankan_cricket_team_in_Bangladesh_in_2013%E2%80%9314","label":"Wikipedia: Sri Lankan cricket team in Bangladesh in 2013-14"},{"url":"https://www.cricket.com.au/news/3239592/sangakkara-smashes-careerbest-319","label":"Cricket Australia: Sangakkara smashes career-best 319"}]},
  29: {"story":"Don Bradman made 304 against England at Leeds, 1934. England made 200. He made 304 off 473 balls and added 388 with Ponsford (181) in Australia's 584. England made 229 for 6 and the match was drawn, with the series level at 1–1.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1934/AUS_IN_ENG/AUS_ENG_T4_20-24JUL1934.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/Australian_cricket_team_in_England_in_1934","label":"Wikipedia: Australia in England, 1934"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  33: {"story":"Brendon McCullum made 302 off 559 balls against India at Wellington in February 2014. New Zealand were 94 for 5 when he came in and he added 352 for the sixth wicket with BJ Watling. The match was drawn and New Zealand won the two-Test series 1-0.","sources":[{"url":"https://en.wikipedia.org/wiki/Indian_cricket_team_in_New_Zealand_in_2013%E2%80%9314","label":"Wikipedia: Indian cricket team in New Zealand in 2013-14"},{"url":"https://www.wisden.com/cricket-features/mens-test-innings-of-the-decade-no-4-brendon-mccullum-dance-with-history","label":"Wisden: Men's Test innings of the decade, No.4, McCullum's dance with history"}]},
  34: {"story":"Don Bradman made 299* against South Africa at Adelaide, 1932. Australia were 3–0 up, so the series was decided. He came in at 1 for 9 and was 299 not out when the last wicket fell, 58% of Australia's 513. Australia then won by ten wickets. He did not play the 5th Test, after twisting an ankle.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1931-32/RSA_IN_AUS/RSA_AUS_T4_29JAN-02FEB1932.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/South_African_cricket_team_in_Australia_in_1931%E2%80%9332","label":"Wikipedia: South Africa in Australia, 1931–32"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  38: {"story":"Viv Richards made 291 off 386 balls against England at The Oval in August 1976, in the fifth and last Test, and it remained his highest Test score. West Indies made 687 for 8 declared and won by 231 runs, taking the series 3-0. He scored 829 runs in the series.","sources":[{"url":"https://en.wikipedia.org/wiki/West_Indian_cricket_team_in_England_in_1976","label":"Wikipedia: West Indian cricket team in England in 1976"},{"url":"https://www.icc-cricket.com/hall-of-fame/hall-of-famers/hall-of-famer-viv-richards","label":"ICC Hall of Fame: Viv Richards"}]},
  44: {"story":"VVS Laxman made 281 off 452 balls against Australia at Eden Gardens, Kolkata, in March 2001. India had been asked to follow on after being bowled out for 171 in reply to 445. He and Rahul Dravid, who made 180, added 376 for the fifth wicket. India declared at 657 for 7 and won by 171 runs, after losing the first Test.","sources":[{"url":"https://en.wikipedia.org/wiki/Australian_cricket_team_in_India_in_2000%E2%80%9301","label":"Wikipedia: Australian cricket team in India in 2000-01"},{"url":"https://www.wisden.com/cricket-news/wisdens-test-innings-of-the-2000s-no-1-vvs-laxmans-281","label":"Wisden: Test innings of the 2000s, No.1, VVS Laxman's 281"}]},
  51: {"story":"Gary Kirsten made 275 against England at Durban in December 1999, in the third Test, with South Africa 1-0 up. South Africa were bowled out for 156 and followed on after England made 366 for 9 declared. He batted for more than 14 hours, the second-longest Test innings, and South Africa made 572 for 7. The match was drawn.","sources":[{"url":"https://en.wikipedia.org/wiki/English_cricket_team_in_South_Africa_in_1999%E2%80%932000","label":"Wikipedia: English cricket team in South Africa in 1999-2000"},{"url":"https://www.wisden.com/wisden-cricketers-almanack/gary-kirsten-more-functional-than-festive-almanack","label":"Wisden: Gary Kirsten, more functional than festive"}]},
  58: {"story":"Don Bradman made 270 against England at Melbourne, 1937. Australia were 0–2 down in the series. They made 200, England were bowled out for 76, and he came in at 5 for 97 and made 270 off 375 balls in Australia's second innings of 564. Australia won by 365 runs, their first win of the series. Wikipedia reports Wisden rating the innings the best Test match innings of all time.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1936-37/ENG_IN_AUS/ENG_AUS_T3_01-07JAN1937.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1936%E2%80%9337_Ashes_series","label":"Wikipedia: 1936–37 Ashes"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  89: {"story":"Rohan Kanhai made 256 against India at Eden Gardens, Calcutta, in the third Test, which began on 31 December 1958. West Indies made 614 for 5 declared and won by an innings and 336 runs, going 2-0 up. They won the series 3-0.","sources":[{"url":"https://en.wikipedia.org/wiki/West_Indian_cricket_team_in_India_in_1958%E2%80%9359","label":"Wikipedia: West Indian cricket team in India in 1958-59"},{"url":"https://www.icc-cricket.com/hall-of-fame/hall-of-famers/hall-of-famer-rohan-kanhai","label":"ICC Hall of Fame: Rohan Kanhai"}]},
  93: {"story":"Don Bradman made 254 against England at Lord's, 1930. England made 425 (Duleepsinhji 173). Australia replied with 729 for 6 declared: he made 254, 35% of it, and Woodfull 155. England made 375, Australia needed 72 and won by seven wickets, levelling the series at 1–1 after the loss at Trent Bridge.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1930/AUS_IN_ENG/AUS_ENG_T2_27JUN-01JUL1930.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1930_Ashes_series","label":"Wikipedia: 1930 Ashes"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  98: {"story":"David Warner made 253 off 286 balls against New Zealand at the WACA, Perth, in November 2015, in the second Test. Ross Taylor replied with 290 and the match was drawn.","sources":[{"url":"https://cricket.com.au/news/david-warner-on-scoring-200-batting-time-james-sutherland-cricket-australia-new-zealand-second-test/2015-11-14","label":"cricket.com.au: Warner on scoring 200"},{"url":"https://www.cricketcountry.com/news/david-warner-dismissed-for-253-by-trent-boult-on-day-2-of-2nd-test-against-new-zealand-353809","label":"Cricket Country: Warner dismissed for 253"}]},
  113: {"story":"Don Bradman made 244 against England at The Oval, 1934. The decider, with the series level 1–1. Australia made 701: he made 244 and Ponsford 266, in a second-wicket stand of 451. England made 321 and 145, and Australia won by 562 runs, taking the Ashes 2–1.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1934/AUS_IN_ENG/AUS_ENG_T5_18-22AUG1934.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/Australian_cricket_team_in_England_in_1934","label":"Wikipedia: Australia in England, 1934"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  124: {"story":"Sachin Tendulkar made 241 not out against Australia at Sydney in January 2004, in the fourth Test with the series level at 1-1. India made 705 for 7 in the first innings and the match was drawn, which left the series drawn 1-1. He was named player of the match.","sources":[{"url":"https://en.wikipedia.org/wiki/Indian_cricket_team_in_Australia_in_2003%E2%80%9304","label":"Wikipedia: Indian cricket team in Australia in 2003-04"},{"url":"https://www.wisden.com/cricket-news/ranked-51-test-hundreds-centuries-sachin-tendulkar","label":"Wisden: Sachin Tendulkar's Test hundreds, ranked"}]},
  146: {"story":"Don Bradman made 234 against England at Sydney, 1946. England made 255. Australia declared at 659 for 8 with Bradman and Barnes both scoring 234. England made 371 and Australia won by an innings and 33 runs.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1940S/1946-47/ENG_IN_AUS/ENG_AUS_T2_13-19DEC1946.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1946%E2%80%9347_Ashes_series","label":"Wikipedia: 1946–47 Ashes"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  152: {"story":"Don Bradman made 232 against England at The Oval, 1930. The decider, with the series level 1–1. England made 405 (Sutcliffe 161). He came in at 1 for 159 and made 232 in Australia's 695, with Ponsford on 110. England made 251 and Australia won by an innings and 39 runs, winning the Ashes 2–1.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1930/AUS_IN_ENG/AUS_ENG_T5_16-22AUG1930.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1930_Ashes_series","label":"Wikipedia: 1930 Ashes"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  172: {"story":"Don Bradman made 226 against South Africa at Brisbane, 1931. The first Test of the series. Australia made 450 and he made 226 of it, half the total, after coming in at 1 for 32. South Africa made 170, followed on and made 117, and Australia won by an innings and 163 runs.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1931-32/RSA_IN_AUS/RSA_AUS_T1_27NOV-03DEC1931.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/South_African_cricket_team_in_Australia_in_1931%E2%80%9332","label":"Wikipedia: South Africa in Australia, 1931–32"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  192: {"story":"Don Bradman made 223 against West Indies at Brisbane, 1931. Australia batted first and made 558 (Ponsford 109). He made 223, 40% of the total. West Indies made 193, followed on and made 148, and Australia won by an innings and 217 runs.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1930-31/WI_IN_AUS/WI_AUS_T3_16-20JAN1931.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/West_Indian_cricket_team_in_Australia_in_1930%E2%80%9331","label":"Wikipedia: West Indies in Australia, 1930–31"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  202: {"story":"Nathan Astle made 222 off 168 balls against England at Christchurch in March 2002, in the first Test. New Zealand were chasing 550 and he reached his double century in 153 balls, the fastest in Test cricket. New Zealand lost by 98 runs.","sources":[{"url":"https://en.wikipedia.org/wiki/English_cricket_team_in_New_Zealand_in_2001%E2%80%9302","label":"Wikipedia: English cricket team in New Zealand in 2001-02"},{"url":"https://en.wikipedia.org/wiki/Nathan_Astle","label":"Wikipedia: Nathan Astle"}]},
  204: {"story":"Sunil Gavaskar made 221 against England at The Oval in the fourth Test of 1979. India were chasing 438 and finished on 429 for 8, nine runs short of a win, and the match was drawn. England won the series 1-0.","sources":[{"url":"https://www.icc-cricket.com/news/classic-knocks-sunil-gavaskar","label":"ICC: Classic knocks, Sunil Gavaskar"},{"url":"https://en.wikipedia.org/wiki/Indian_cricket_team_in_England_in_1979","label":"Wikipedia: Indian cricket team in England in 1979"}]},
  213: {"story":"Bill Edrich made 219 against South Africa at Durban in March 1939, in the fifth Test, which was played to a finish with no time limit. England were set 696 to win and were 654 for 5 when the match was abandoned as a draw so the team could catch its boat home, after nine days of play. England had led the series 1-0 and won it 1-0.","sources":[{"url":"https://en.wikipedia.org/wiki/English_cricket_team_in_South_Africa_in_1938%E2%80%9339","label":"Wikipedia: English cricket team in South Africa in 1938-39"},{"url":"https://en.wikipedia.org/wiki/Timeless_Test","label":"Wikipedia: Timeless Test"}]},
  215: {"story":"Mark Taylor made 219 against England at Trent Bridge in the fifth Test of the 1989 Ashes. He and Geoff Marsh added 329 for the first wicket, the highest opening stand in Anglo-Australian cricket. Australia won by an innings and 180 runs and took the series 4-0.","sources":[{"url":"https://en.wikipedia.org/wiki/Australian_cricket_team_in_England_in_1989","label":"Wikipedia: Australian cricket team in England in 1989"},{"url":"https://www.wisden.com/wisden-cricketers-almanack/how-a-young-mark-taylor-dominated-england-on-his-maiden-ashes-tour-almanack","label":"Wisden: How a young Mark Taylor dominated England on his maiden Ashes tour"}]},
  245: {"story":"Gordon Greenidge made 214 not out off 242 balls against England at Lord's in the summer of 1984, in the second Test. West Indies were chasing 342 after David Gower declared in England's second innings, and won by nine wickets, with Greenidge sharing an unbroken stand of 287 with Larry Gomes. West Indies won the series 5-0.","sources":[{"url":"https://en.wikipedia.org/wiki/West_Indian_cricket_team_in_England_in_1984","label":"Wikipedia: West Indian cricket team in England in 1984"},{"url":"https://www.wisden.com/cricket-features/lithe-debonair-and-quite-brilliant-the-west-indies-class-of-1984","label":"Wisden: Lithe, debonair and quite brilliant, the West Indies class of 1984"}]},
  260: {"story":"Don Bradman made 212 against England at Adelaide, 1937. The series stood at 1–2. Australia made 288, England 330. He came in at 1 for 21 and made 212 off 395 balls in Australia's second innings of 433. Australia won by 148 runs and levelled the series at 2–2.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1936-37/ENG_IN_AUS/ENG_AUS_T4_29JAN-04FEB1937.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1936%E2%80%9337_Ashes_series","label":"Wikipedia: 1936–37 Ashes"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  334: {"story":"Adam Gilchrist made 204 not out off 213 balls against South Africa at Johannesburg in February 2002, in the first Test of the series. At the time it was the fastest Test double century. He added 317 for the sixth wicket with Damien Martyn, Australia made 652 for 7 declared and won by an innings and 360 runs.","sources":[{"url":"https://www.cricket.com.au/news/adam-gilchrist-australia-south-africa-double-century-204-johannesburg-martyn-hayden-mcgrath-warne/2018-02-23","label":"Cricket Australia: When Gilchrist went berserk in Jo'burg"},{"url":"https://en.wikipedia.org/wiki/Australian_cricket_team_in_South_Africa_in_2001%E2%80%9302","label":"Wikipedia: Australian cricket team in South Africa in 2001-02"}]},
  363: {"story":"Justin Greaves made 202 not out off 388 balls against New Zealand at Christchurch in the first Test of the 2025-26 series. West Indies were set 531 to win and finished the fourth innings on 457 for 6, and the match was drawn. New Zealand won the series 2-0.","sources":[{"url":"https://en.wikipedia.org/wiki/West_Indian_cricket_team_in_New_Zealand_in_2025%E2%80%9326","label":"Wikipedia: West Indian cricket team in New Zealand in 2025-26"},{"url":"https://www.wisden.com/series/new-zealand-vs-west-indies-m-2025/cricket-features/where-do-greaves-and-roach-rank-the-top-15-match-saving-acts-in-test-cricket-history","label":"Wisden: The top 15 match-saving acts in Test cricket history"}]},
  379: {"story":"Don Bradman made 201 against India at Adelaide, 1948. Australia made 674, the highest total of the series. He made 201 off 296 balls, adding 236 for the second wicket with Barnes (112). India made 381 and followed on, and Australia won by an innings and 16 runs, clinching the series.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1940S/1947-48/IND_IN_AUS/IND_AUS_T4_23-28JAN1948.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/Indian_cricket_team_in_Australia_in_1947%E2%80%9348","label":"Wikipedia: India in Australia, 1947–48"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  413: {"story":"Steve Waugh made 200 against West Indies at Kingston in 1995, in the fourth Test with the series level at 1-1. His brother Mark made 126 in the same innings. Australia won by an innings and 53 runs and took the series 2-1.","sources":[{"url":"https://www.wisden.com/cricket-news/bob-simpson-doesnt-get-credit-story-behind-steve-waughs-200-v-west-indies","label":"Wisden: The story behind Steve Waugh's 200 v West Indies"},{"url":"https://www.cricket.com.au/news/3276066/australia-beat-west-indies-1995-test-series-victory-dawn-of-a-golden-age-australian-cricket-mark-taylor-waugh-warne","label":"Cricket Australia: The dawn of a golden age for Australia"}]},
  456: {"story":"Babar Azam made 196 off 425 balls against Australia at Karachi in March 2022, in the second Test. Pakistan were set 506 and had to chase it or survive the last day. Babar was out four runs short of a double hundred, Mohammad Rizwan reached a century in the penultimate over, and the match was drawn.","sources":[{"url":"https://en.wikipedia.org/wiki/Australian_cricket_team_in_Pakistan_in_2021%E2%80%9322","label":"Wikipedia: Australian cricket team in Pakistan in 2021-22"},{"url":"https://www.icc-cricket.com/news/brilliant-babar-rizwan-tons-secure-thrilling-draw-in-karachi","label":"ICC: Brilliant Babar, Rizwan tons secure thrilling draw in Karachi"}]},
  488: {"story":"Kumar Sangakkara made 192 off 282 balls against Australia at Hobart in November 2007, in the second Test, after making 57 in the first innings. Sri Lanka were chasing 507 and he was the last man out, given caught when, according to Cricket Australia, the ball had come off his helmet. Australia won by 96 runs and took the series 2-0.","sources":[{"url":"https://en.wikipedia.org/wiki/Sri_Lankan_cricket_team_in_Australia_in_2007%E2%80%9308","label":"Wikipedia: Sri Lankan cricket team in Australia in 2007-08"},{"url":"https://www.cricket.com.au/news/legends-month-kumar-sangakkara-hobart-sri-lanka-australia-test-2007-video-highlights/2018-05-03","label":"Cricket Australia: Legends Month, the best of Sangakkara"}]},
  536: {"story":"Don Bradman made 187 against England at Brisbane, 1946. Australia made 645 and he made 187 off 313 balls after coming in at 1 for 9. England made 141, followed on and made 172, and Australia won by an innings and 332 runs.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1940S/1946-47/ENG_IN_AUS/ENG_AUS_T1_29NOV-04DEC1946.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1946%E2%80%9347_Ashes_series","label":"Wikipedia: 1946–47 Ashes"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  552: {"story":"Mike Atherton made 185 not out against South Africa at Johannesburg in the second Test of 1995-96, batting for 643 minutes. England had been bowled out for 200 in the first innings and were 351 for 5 after 165 overs in the fourth when the match ended in a draw.","sources":[{"url":"https://en.wikipedia.org/wiki/English_cricket_team_in_South_Africa_in_1995%E2%80%9396","label":"Wikipedia: English cricket team in South Africa in 1995-96"},{"url":"https://www.wisden.com/series/new-zealand-vs-west-indies-m-2025/cricket-features/where-do-greaves-and-roach-rank-the-top-15-match-saving-acts-in-test-cricket-history","label":"Wisden: The top 15 match-saving acts in Test cricket history"}]},
  553: {"story":"Don Bradman made 185 against India at Brisbane, 1947. Australia made 382 for 8 declared, with rain limiting play. He made 185 with 20 fours and was 160 not out at the end of the first day. India made 58 and 98 and Australia won by an innings and 226 runs.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1940S/1947-48/IND_IN_AUS/IND_AUS_T1_28NOV-04DEC1947.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/Indian_cricket_team_in_Australia_in_1947%E2%80%9348","label":"Wikipedia: India in Australia, 1947–48"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  724: {"story":"Don Bradman made 173* against England at Leeds, 1948. England made 496 and declared at 365 for 8, setting Australia 404 to win. He came in at 1 for 57 and made 173 not out in 255 minutes, adding 301 with Morris (182). He was dropped on 108 and was troubled by fibrositis. Australia won by seven wickets, a record successful chase in Tests at the time.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1940S/1948/AUS_IN_ENG/AUS_ENG_T4_22-27JUL1948.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1948_Ashes_series","label":"Wikipedia: 1948 Ashes"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  782: {"story":"Don Bradman made 169 against England at Melbourne, 1937. The decider, with the series level 2–2 after Australia had been 0–2 down. He made 169 off 191 balls in a total of 604, with McCabe and Badcock also making hundreds. England made 239 and 165 and Australia won by an innings and 200 runs.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1936-37/ENG_IN_AUS/ENG_AUS_T5_26FEB-03MAR1937.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1936%E2%80%9337_Ashes_series","label":"Wikipedia: 1936–37 Ashes"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  811: {"story":"Don Bradman made 167 against South Africa at Melbourne, 1931. Australia made 198 in the first innings and South Africa 358. He came in at 1 for 54, 106 behind, and made 167 in the 554 that followed. Australia won by 169 runs.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1931-32/RSA_IN_AUS/RSA_AUS_T3_31DEC1931-06JAN1932.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/South_African_cricket_team_in_Australia_in_1931%E2%80%9332","label":"Wikipedia: South Africa in Australia, 1931–32"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  1075: {"story":"Ricky Ponting made 156 off 275 balls against England at Old Trafford in August 2005. Australia were chasing 423 and held on for a draw, which kept the Ashes level at 1-1.","sources":[{"url":"https://www.wisden.com/cricket-news/pontings-156-wisdens-test-innings-of-the-2000s-no-3","label":"Wisden: Test innings of the 2000s, No.3, Ponting's 156"},{"url":"https://www.cricket.com.au/news/ricky-ponting-ashes-australia-england-old-trafford-manchester-2005-on-this-day-best-test-innings-156/2018-08-15","label":"Cricket Australia: When captain Ponting defied England in epic rearguard"}]},
  1118: {"story":"Graeme Smith made 154 not out off 246 balls against England at Edgbaston in the third Test of 2008, with South Africa 1-0 up. South Africa were chasing 281 and won by five wickets, and Smith was player of the match. They won the series 2-1, their first in England since returning to international cricket.","sources":[{"url":"https://en.wikipedia.org/wiki/South_African_cricket_team_in_England_in_2008","label":"Wikipedia: South African cricket team in England in 2008"},{"url":"https://www.icc-cricket.com/news/graeme-smith-the-born-leader-who-made-south-africa-believe","label":"ICC: Graeme Smith, the born leader who made South Africa believe"}]},
  1142: {"story":"Brian Lara made 153 not out off 256 balls against Australia at Kensington Oval, Bridgetown, in March 1999, with the series level at 1-1. West Indies were chasing in the fourth innings and won by one wicket.","sources":[{"url":"https://en.wikipedia.org/wiki/Australian_cricket_team_in_the_West_Indies_in_1998%E2%80%9399","label":"Wikipedia: Australian cricket team in the West Indies in 1998-99"},{"url":"https://www.windiescricket.com/news/brian-lara-unforgettable-west-indian-innings/","label":"Windies Cricket: Brian Lara, unforgettable West Indian innings"}]},
  1185: {"story":"Don Bradman made 152 against West Indies at Melbourne, 1931. Australia were already 3–0 up, so the series was decided. West Indies made 99, Australia declared at 328 for 8 with his 152, West Indies made 107 and Australia won by an innings and 122 runs.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1930-31/WI_IN_AUS/WI_AUS_T4_13-14FEB1931.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/West_Indian_cricket_team_in_Australia_in_1930%E2%80%9331","label":"Wikipedia: West Indies in Australia, 1930–31"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  1275: {"story":"Adam Gilchrist made 149 not out against Pakistan at Hobart in November 1999, in his second Test and the second of the series, with Australia 1-0 up. Australia were chasing 369 and were 126 for 5 when he came in. He added 238 with Justin Langer and Australia won.","sources":[{"url":"https://www.wisden.com/cricket-news/wisdens-test-innings-of-the-1990s-no-4-adam-gilchrists-149","label":"Wisden: Test innings of the 1990s, No.4, Adam Gilchrist's 149*"},{"url":"https://www.cricket.com.au/news/justin-langer-1999-hobart-test-pakistan-australia-partnership-record-finest-moment-gilchrist/2017-04-06","label":"Cricket Australia: Langer recalls his finest Test moment"}]},
  1428: {"story":"Don Bradman made 144* against England at Nottingham, 1938. England made 658 for 8 declared. Australia made 411, followed on, and he made 144 not out off 379 balls with Brown's hundred, as Australia reached 427 for 6 declared. The match was drawn.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1938/AUS_IN_ENG/AUS_ENG_T1_10-14JUN1938.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1938_Ashes_series","label":"Wikipedia: 1938 Ashes"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  1451: {"story":"Steve Smith made 144 on the first day of the first Ashes Test at Edgbaston in August 2019, on his return to Test cricket after a year-long suspension. He added 88 for the ninth wicket with Peter Siddle and Australia were bowled out for 284. He made 142 in the second innings and Australia won by 251 runs.","sources":[{"url":"https://www.cricket.com.au/news/match-report/day-one-australia-england-first-ashes-test-live-scores-radio-watch-video-highlights-edgbaston/2019-08-02","label":"Cricket Australia: day one match report, Edgbaston 2019"},{"url":"https://www.cricket.com.au/news/steve-smith-two-twin-centuries-ashes-test-edgbaston-australia-england-matthew-hayden-steve-waugh/2019-08-05","label":"Cricket Australia: Smith completes rare Ashes double"},{"url":"https://en.wikipedia.org/wiki/2019_Ashes_series","label":"Wikipedia: 2019 Ashes series"}]},
  1661: {"story":"Don Bradman made 138 against England at Nottingham, 1948. England were bowled out for 165. Australia replied with 509, and he made 138 in 290 minutes against a defensive field. Wikipedia describes it as one of his slower innings, and Hassett also made a hundred. Australia won by eight wickets.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1940S/1948/AUS_IN_ENG/AUS_ENG_T1_10-15JUN1948.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1948_Ashes_series","label":"Wikipedia: 1948 Ashes"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  1823: {"story":"Ben Stokes made 135 not out off 219 balls against Australia at Headingley in August 2019. England had been bowled out for 67 in the first innings. He and Jack Leach added 76 for the last wicket and England won by one wicket, levelling the series at 1-1.","sources":[{"url":"https://www.icc-cricket.com/news/ben-stokes-remarkable-135-leads-england-to-incredible-one-wicket-victory","label":"ICC: Ben Stokes' remarkable 135* leads England to a one-wicket victory"},{"url":"https://www.wisden.com/cricket-news/mens-test-innings-of-the-decade-no-1-ben-stokes-reaches-his-apex","label":"Wisden: Men's Test innings of the decade, No.1"}]},
  1943: {"story":"Don Bradman made 132 against India at Melbourne, 1948. His first of two hundreds in the one Test. He made 132 off 204 balls in Australia's 394. India made 291 for 9 declared.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1940S/1947-48/IND_IN_AUS/IND_AUS_T3_01-05JAN1948.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/Indian_cricket_team_in_Australia_in_1947%E2%80%9348","label":"Wikipedia: India in Australia, 1947–48"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  1978: {"story":"Don Bradman made 131 against England at Nottingham, 1930. Australia were set 429 to win. He came in at 1 for 12 and made 131 off 287 balls, but Australia were bowled out for 335 and England won by 93 runs.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1930/AUS_IN_ENG/AUS_ENG_T1_13-17JUN1930.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1930_Ashes_series","label":"Wikipedia: 1930 Ashes"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  2137: {"story":"Don Bradman made 127* against India at Melbourne, 1948. His second hundred in the same Test, and the first time he had made a hundred in each innings. He came in at 4 for 32 and shared an unbeaten 223 with Morris (100 not out) before Australia declared at 255 for 4, setting India 359. India made 125 and Australia won by 233 runs.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1940S/1947-48/IND_IN_AUS/IND_AUS_T3_01-05JAN1948.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/Indian_cricket_team_in_Australia_in_1947%E2%80%9348","label":"Wikipedia: India in Australia, 1947–48"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  2361: {"story":"Don Bradman made 123 against England at Melbourne, 1929. England had already won the first four Tests and retained the Ashes, so this was a dead rubber. He made 123 off 247 balls, with Woodfull on 102, and Australia chased down 287 to win by five wickets.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1920S/1928-29/ENG_IN_AUS/ENG_AUS_T5_08-16MAR1929.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/English_cricket_team_in_Australia_in_1928%E2%80%9329","label":"Wikipedia: England in Australia, 1928–29"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  3179: {"story":"Don Bradman made 112 against England at Melbourne, 1928. Australia's second innings in the 3rd Test at the MCG. He made 112 off 281 balls and Woodfull made 107, but England chased the runs and won by three wickets with 7 for 332. The match still holds the record for the highest match aggregate without a no-ball extra (1,497).","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1920S/1928-29/ENG_IN_AUS/ENG_AUS_T3_29DEC1928-05JAN1929.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/English_cricket_team_in_Australia_in_1928%E2%80%9329","label":"Wikipedia: England in Australia, 1928–29"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  3181: {"story":"Don Bradman made 112 against South Africa at Sydney, 1931. Australia made 469, with Rigg's 127 and his 112. South Africa made 153 and 161 and Australia won by an innings and 155 runs.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1931-32/RSA_IN_AUS/RSA_AUS_T2_18-21DEC1931.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/South_African_cricket_team_in_Australia_in_1931%E2%80%9332","label":"Wikipedia: South Africa in Australia, 1931–32"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  4021: {"story":"Don Bradman made 103* against England at Melbourne, 1932. The 2nd Bodyline Test, with England 1–0 up. He was out first ball in the first innings, then made 103 not out of Australia's 191 against the full Bodyline attack. Australia won by 111 runs and levelled the series. His reputation, which had slipped after earlier failures, was restored.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1932-33/ENG_IN_AUS/ENG_AUS_T2_30DEC1932-03JAN1933.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/Bodyline","label":"Wikipedia: Bodyline"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  4065: {"story":"Don Bradman made 103 against England at Leeds, 1938. A match completed in three days. England made 223, and he made 103 of Australia's 242. England made 123 and Australia won by five wickets, and went on to retain the Ashes.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1938/AUS_IN_ENG/AUS_ENG_T4_22-25JUL1938.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1938_Ashes_series","label":"Wikipedia: 1938 Ashes"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  4162: {"story":"Don Bradman made 102* against England at Lord's, 1938. England made 494 and declared at 242 for 8, setting Australia 315. He came in at 1 for 8 and made 102 not out off 135 balls, half of Australia's 204 for 6. The match was drawn.","sources":[{"url":"https://i.imgci.com/db/ARCHIVE/1930S/1938/AUS_IN_ENG/AUS_ENG_T2_24-28JUN1938.html","label":"Scorecard (Cricinfo archive)"},{"url":"https://en.wikipedia.org/wiki/1938_Ashes_series","label":"Wikipedia: 1938 Ashes"},{"url":"https://en.wikipedia.org/wiki/List_of_international_cricket_centuries_by_Don_Bradman","label":"Wikipedia: Bradman’s Test centuries"}]},
  4599: {"story":"Matt Renshaw made 190 off 397 balls against South Africa at Kingsmead, Durban, in the first Test of 2026. Australia were 6 for 124 when he added 134 for the ninth wicket with Nathan Lyon, Australia's best for that wicket since 1894, and they reached 390. Australia won by 214 runs.","sources":[{"url":"https://www.icc-cricket.com/news/renshaw-s-190-puts-australia-in-control-in-durban","label":"ICC: Renshaw’s 190 puts Australia in control in Durban"},{"url":"https://www.cricket.com.au/news/4590262/matthew-renshaw-century-decade-190-10-years-south-africa-australia-first-test-kingsmead-failures-dropped-comeback","label":"cricket.com.au: How failures helped Renshaw achieve his magnum opus"}]},
};
